## Assignment:
Write a function `withdraw(balance: number, amount: number): number` that:
- Throws `new Error("Insufficient funds")` if amount > balance
- Throws `new Error("Invalid amount")` if amount <= 0
- Returns balance - amount otherwise

runHarness:
let _pass = 0;
let _fail = 0;
function _test(num: number, got: any, expected: any) {
    const passed = got === expected;
    console.log('---------------------');
    console.log('Test ' + num + ':');
    console.log('Output: ' + got);
    console.log(passed ? 'Pass' : 'Fail');
    if (passed) _pass++; else _fail++;
}
_test(1, withdraw(100, 50), 50);
_test(2, withdraw(100, 100), 0);
_test(3, withdraw(500, 1), 499);
try { withdraw(100, 200); _test(4, 'no error', 'Insufficient funds'); } catch(e: any) { _test(4, e.message, 'Insufficient funds'); }
try { withdraw(100, 0); _test(5, 'no error', 'Invalid amount'); } catch(e: any) { _test(5, e.message, 'Invalid amount'); }
try { withdraw(100, -10); _test(6, 'no error', 'Invalid amount'); } catch(e: any) { _test(6, e.message, 'Invalid amount'); }
console.log('---------------------');
console.log(_pass + ' passed, ' + _fail + ' failed');

